pkg_path = 'Tomorrow_is_Still_Open_Publishing_Package.zip'
# The new REVISED.html and .md are just rebuilt, .pdf is rebuilt
# cover.png should still be valid (the cover image hasn't changed)

files_to_package = {
    'Tomorrow_is_Still_Open_REVISED.html': 'Tomorrow_is_Still_Open_REVISED.html',
    'Tomorrow_is_Still_Open_FINAL.pdf': 'Tomorrow_is_Still_Open_REVISED.pdf',
    'Tomorrow_is_Still_Open_REVISED.md': 'Tomorrow_is_Still_Open_REVISED.md',
}

# Check if cover exists somewhere
cover_src = None
for p in ['cover.png', '../Tomorrow_is_Still_Open_Cover.png', '../output/cover.png']:
    full = os.path.join(os.path.dirname(pkg_path) if '/' in pkg_path else '.', p)
    abs_p = os.path.abspath(full)
    if os.path.exists(abs_p):
        cover_src = abs_p
        break

if cover_src:
    files_to_package[cover_src] = 'cover.png'
    print(f'Cover: {cover_src}')
else:
    # Try the publishing package dir
    base = '/home/bob/books/The_Unwritten_Future'
    for p in [os.path.join(base, 'Tomorrow_is_Still_Open_Cover.png'),
              os.path.join(base, 'output', 'cover.png'),
              os.path.join(base, 'generated_images', 'Tomorrow_is_Still_Open_KDP_Kindle_Cover.jpg')]:
        if os.path.exists(p):
            files_to_package[p] = os.path.basename(p)
            print(f'Cover fallback: {p}')
            break

with zipfile.ZipFile(pkg_path, 'w', zipfile.ZIP_DEFLATED) as z:
    for src, arcname in files_to_package.items():
        if src and os.path.exists(src):
            z.write(src, arcname)
            print(f'  Added {arcname} ({os.path.getsize(src):,} bytes)')
        else:
            print(f'  MISSING: {src}')

print(f'\\nPackage size: {os.path.getsize(pkg_path):,} bytes')
